// AscendC AddLayerNormQuant kernel
// Add(x1, x2 [+bias]) -> LayerNorm(gamma, beta) -> Quantize(int8)
// Single-row strategy: process one full row at a time
// Supports float32, float16, bfloat16 inputs

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void PrepareInputTensor(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void PrepareOutputTensor(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &out,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = out.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Duplicate(out, static_cast<T>(0), count);
    }
}

// =========================================================================
// Kernel class
// =========================================================================

template <typename dataType>
class AddLayerNormQuantKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x1, GM_ADDR x2,
        GM_ADDR gamma, GM_ADDR beta, GM_ADDR bias,
        GM_ADDR scales1, GM_ADDR scales2,
        GM_ADDR y1_int8, GM_ADDR y2_int8,
        GM_ADDR x_out, GM_ADDR out_scale1, GM_ADDR out_scale2,
        int32_t M, int32_t N,
        int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
        float eps, int64_t quantMode, int64_t hasBias)
    {
        this->M = M;
        this->N = N;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->eps = eps;
        this->quantMode = quantMode;
        this->hasBias = hasBias;

        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), static_cast<uint64_t>(M) * N);
        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), static_cast<uint64_t>(M) * N);
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gamma), N);
        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(beta), N);
        biasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(bias), N);
        scales1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scales1), N);
        scales2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scales2), N);
        y1Int8GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y1_int8), static_cast<uint64_t>(M) * N);
        y2Int8GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y2_int8), static_cast<uint64_t>(M) * N);
        xOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x_out), static_cast<uint64_t>(M) * N);
        outScale1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(out_scale1), M);
        outScale2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(out_scale2), M);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockM / AscendC::GetSubBlockNum();

        // TQue buffers for row data I/O
        pipe.InitBuffer(x1InQueue_, BUFFER_NUM, N * sizeof(dataType));
        pipe.InitBuffer(x2InQueue_, BUFFER_NUM, N * sizeof(dataType));
        pipe.InitBuffer(xOutQueue_, BUFFER_NUM, N * sizeof(dataType));
        pipe.InitBuffer(y1Int8OutQueue_, BUFFER_NUM, N * sizeof(int8_t));
        pipe.InitBuffer(y2Int8OutQueue_, BUFFER_NUM, N * sizeof(int8_t));
        pipe.InitBuffer(outScaleQueue_, BUFFER_NUM, 2 * sizeof(float));

        // TBuf for stored weight tensors (loaded once, used for all rows)
        pipe.InitBuffer(gammaBuf_, N * sizeof(float));
        pipe.InitBuffer(betaBuf_, N * sizeof(float));
        if (quantMode == 1) {
            pipe.InitBuffer(scales1Buf_, N * sizeof(float));
            pipe.InitBuffer(scales2Buf_, N * sizeof(float));
        }
        if (hasBias) {
            pipe.InitBuffer(biasBuf_, N * sizeof(dataType));
        }

        // Cast buffers for fp16/bf16 -> fp32 conversion
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(x1CastBuf_, N * sizeof(float));
            pipe.InitBuffer(x2CastBuf_, N * sizeof(float));
            pipe.InitBuffer(xOutCastBuf_, N * sizeof(float));
            if (hasBias) {
                pipe.InitBuffer(biasCastBuf_, N * sizeof(float));
            }
        }

        // Work buffers for fp32 computation
        pipe.InitBuffer(workBufA_, N * sizeof(float));
        pipe.InitBuffer(workBufB_, N * sizeof(float));
        pipe.InitBuffer(workBufC_, N * sizeof(float));
        pipe.InitBuffer(reduceBuf_, 2 * N * sizeof(uint8_t));
        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));

        // Preload gamma (persistent across all rows)
        gammaLocal_ = gammaBuf_.Get<float>();
        LoadGmToUb(gammaLocal_, gammaGM_, static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // Preload beta
        betaLocal_ = betaBuf_.Get<float>();
        LoadGmToUb(betaLocal_, betaGM_, static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // Preload scales if static quant
        if (quantMode == 1) {
            scales1Local_ = scales1Buf_.Get<float>();
            LoadGmToUb(scales1Local_, scales1GM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();

            scales2Local_ = scales2Buf_.Get<float>();
            LoadGmToUb(scales2Local_, scales2GM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
        }

        // Preload bias if needed
        if (hasBias) {
            biasInLocal_ = biasBuf_.Get<dataType>();
            LoadGmToUb(biasInLocal_, biasGM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            PrepareInputTensor<dataType>(biasFp32Local_, biasInLocal_, biasCastBuf_, N);
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx * blockM >= M) { continue; }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    // =====================================================================
    // Per-row: CopyIn -> Compute -> CopyOut pipeline
    // =====================================================================

    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        CopyIn(rowIdx);
        Compute();
        CopyOut(rowIdx);
    }

    __aicore__ inline void CopyIn(int32_t rowIdx)
    {
        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x1InLocal_, x1GM_[static_cast<uint64_t>(rowIdx) * N],
                    static_cast<uint32_t>(N));
        x1InQueue_.EnQue(x1InLocal_);

        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
        LoadGmToUb(x2InLocal_, x2GM_[static_cast<uint64_t>(rowIdx) * N],
                    static_cast<uint32_t>(N));
        x2InQueue_.EnQue(x2InLocal_);
    }

    __aicore__ inline void Compute()
    {
        // ── Allocate output tensors ──
        xOutLocal_ = xOutQueue_.AllocTensor<dataType>();
        y1Int8OutLocal_ = y1Int8OutQueue_.AllocTensor<int8_t>();
        y2Int8OutLocal_ = y2Int8OutQueue_.AllocTensor<int8_t>();
        outScaleLocal_ = outScaleQueue_.AllocTensor<float>();

        // ── Get work buffers ──
        workA_ = workBufA_.Get<float>();
        workB_ = workBufB_.Get<float>();
        workC_ = workBufC_.Get<float>();
        reduceTmp_ = reduceBuf_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();

        // ── DeQue inputs ──
        x1InLocal_ = x1InQueue_.DeQue<dataType>();
        x2InLocal_ = x2InQueue_.DeQue<dataType>();

        // ── Cast inputs to fp32 ──
        PrepareInputTensor<dataType>(x1Fp32_, x1InLocal_, x1CastBuf_, N);
        PrepareInputTensor<dataType>(x2Fp32_, x2InLocal_, x2CastBuf_, N);
        PrepareOutputTensor<dataType>(xOutFp32_, xOutLocal_, xOutCastBuf_, N);

        // =============================================================
        // Phase 1: x_out = x1 + x2 [+ bias]
        // =============================================================
        AscendC::Add(xOutFp32_, x1Fp32_, x2Fp32_, N);

        if (hasBias) {
            AscendC::Add(xOutFp32_, xOutFp32_, biasFp32Local_, N);
        }

        // Cast x_out to input dtype and enqueue for CopyOut
        if constexpr (!std::is_same_v<dataType, float>) {
            AscendC::Cast(xOutLocal_, xOutFp32_, OutputRoundModeHelper<dataType>(), N);
            AscendC::PipeBarrier<PIPE_V>();
        }
        xOutQueue_.EnQue(xOutLocal_);

        // =============================================================
        // Phase 2: LayerNorm stats (mean, var, rstd)
        // =============================================================
        // sum_x = ReduceSum(x_out) — scalar value
        AscendC::ReduceSum<float>(sumLocal_, xOutFp32_, reduceTmp_, N);
        AscendC::PipeBarrier<PIPE_V>();
        float sumX = sumLocal_.GetValue(0);

        // sum_x2 = ReduceSum(x_out^2)
        AscendC::Mul(workA_, xOutFp32_, xOutFp32_, N);
        AscendC::ReduceSum<float>(sumLocal_, workA_, reduceTmp_, N);
        AscendC::PipeBarrier<PIPE_V>();
        float sumX2 = sumLocal_.GetValue(0);

        float invN = 1.0f / static_cast<float>(N);
        float meanVal = sumX * invN;
        float varVal = sumX2 * invN - meanVal * meanVal;
        float rstdVal = 1.0f / AscendC::Sqrt(varVal + eps);

        // =============================================================
        // Phase 3: Layernorm y = (x - mean) * rstd * gamma + beta
        // =============================================================
        // workA = (xOut - mean) * rstd
        AscendC::Adds(workA_, xOutFp32_, -meanVal, N);
        AscendC::Muls(workA_, workA_, rstdVal, N);

        // workB = workA * gamma + beta (this is y in fp32)
        AscendC::Mul(workB_, workA_, gammaLocal_, N);
        AscendC::Add(workB_, workB_, betaLocal_, N);

        // =============================================================
        // Phase 4: Quantize y to int8
        // =============================================================
        float outScale1Val, outScale2Val;

        if (quantMode == 1) {
            // Static quant: y1 = y * scales1, y2 = y * scales2
            // Quantize y1
            AscendC::Mul(workC_, workB_, scales1Local_, N);
            AscendC::Abs(workA_, workC_, N);
            AscendC::ReduceMax<float>(sumLocal_, workA_, reduceTmp_, N);
            AscendC::PipeBarrier<PIPE_V>();
            outScale1Val = sumLocal_.GetValue(0) / 127.0f;

            // Scale and clamp y1
            float invScale1 = 1.0f / (outScale1Val + 1e-12f);
            AscendC::Muls(workA_, workC_, invScale1, N);
            // Clamp to [-128, 127]
            AscendC::Maxs(workB_, workA_, -128.0f, N);
            AscendC::Mins(workC_, workB_, 127.0f, N);
            // Cast float -> int8
            AscendC::Cast(y1Int8OutLocal_, workC_, AscendC::RoundMode::CAST_RINT, N);

            // Quantize y2
            AscendC::Mul(workA_, workB_, scales2Local_, N);
            AscendC::Abs(workB_, workA_, N);
            AscendC::ReduceMax<float>(sumLocal_, workB_, reduceTmp_, N);
            AscendC::PipeBarrier<PIPE_V>();
            outScale2Val = sumLocal_.GetValue(0) / 127.0f;

            float invScale2 = 1.0f / (outScale2Val + 1e-12f);
            AscendC::Muls(workB_, workA_, invScale2, N);
            AscendC::Maxs(workC_, workB_, -128.0f, N);
            AscendC::Mins(workA_, workC_, 127.0f, N);
            AscendC::Cast(y2Int8OutLocal_, workA_, AscendC::RoundMode::CAST_RINT, N);
        } else {
            // Dynamic quant: y1_int8 = quantize(y), y2_int8 = zeros
            AscendC::Abs(workA_, workB_, N);
            AscendC::ReduceMax<float>(sumLocal_, workA_, reduceTmp_, N);
            AscendC::PipeBarrier<PIPE_V>();
            outScale1Val = sumLocal_.GetValue(0) / 127.0f;

            // Scale and clamp y1
            float invScale1 = 1.0f / (outScale1Val + 1e-12f);
            AscendC::Muls(workA_, workB_, invScale1, N);
            AscendC::Maxs(workC_, workA_, -128.0f, N);
            AscendC::Mins(workB_, workC_, 127.0f, N);
            AscendC::Cast(y1Int8OutLocal_, workB_, AscendC::RoundMode::CAST_RINT, N);

            // y2_int8 = zeros
            AscendC::Duplicate(y2Int8OutLocal_, static_cast<int8_t>(0), N);

            outScale2Val = outScale1Val;
        }

        // =============================================================
        // Phase 5: EnQue outputs
        // =============================================================
        y1Int8OutQueue_.EnQue(y1Int8OutLocal_);
        y2Int8OutQueue_.EnQue(y2Int8OutLocal_);

        // Write out_scale values to a 2-element tensor
        outScaleLocal_.SetValue(0, outScale1Val);
        outScaleLocal_.SetValue(1, outScale2Val);
        outScaleQueue_.EnQue(outScaleLocal_);

        // Free input tensors
        x1InQueue_.FreeTensor(x1InLocal_);
        x2InQueue_.FreeTensor(x2InLocal_);
    }

    __aicore__ inline void CopyOut(int32_t rowIdx)
    {
        // CopyOut x_out
        xOutLocal_ = xOutQueue_.DeQue<dataType>();
        StoreUbToGm(xOutGM_[static_cast<uint64_t>(rowIdx) * N],
                    xOutLocal_, static_cast<uint32_t>(N));
        xOutQueue_.FreeTensor(xOutLocal_);

        // CopyOut y1_int8
        y1Int8OutLocal_ = y1Int8OutQueue_.DeQue<int8_t>();
        StoreUbToGm(y1Int8GM_[static_cast<uint64_t>(rowIdx) * N],
                    y1Int8OutLocal_, static_cast<uint32_t>(N));
        y1Int8OutQueue_.FreeTensor(y1Int8OutLocal_);

        // CopyOut y2_int8
        y2Int8OutLocal_ = y2Int8OutQueue_.DeQue<int8_t>();
        StoreUbToGm(y2Int8GM_[static_cast<uint64_t>(rowIdx) * N],
                    y2Int8OutLocal_, static_cast<uint32_t>(N));
        y2Int8OutQueue_.FreeTensor(y2Int8OutLocal_);

        // CopyOut out_scales (2-element float tensor: {scale1, scale2})
        outScaleLocal_ = outScaleQueue_.DeQue<float>();
        float s1 = outScaleLocal_.GetValue(0);
        float s2 = outScaleLocal_.GetValue(1);
        outScale1GM_[rowIdx] = s1;
        outScale2GM_[rowIdx] = s2;
        outScaleQueue_.FreeTensor(outScaleLocal_);
    }

private:
    int32_t M = 0;
    int32_t N = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    float eps = 0.0f;
    int64_t quantMode = 0;
    int64_t hasBias = 0;
    int subBlockRows_ = 0;

    AscendC::TPipe pipe;

    // Global tensors
    AscendC::GlobalTensor<dataType> x1GM_;
    AscendC::GlobalTensor<dataType> x2GM_;
    AscendC::GlobalTensor<float> gammaGM_;
    AscendC::GlobalTensor<float> betaGM_;
    AscendC::GlobalTensor<dataType> biasGM_;
    AscendC::GlobalTensor<float> scales1GM_;
    AscendC::GlobalTensor<float> scales2GM_;
    AscendC::GlobalTensor<int8_t> y1Int8GM_;
    AscendC::GlobalTensor<int8_t> y2Int8GM_;
    AscendC::GlobalTensor<dataType> xOutGM_;
    AscendC::GlobalTensor<float> outScale1GM_;
    AscendC::GlobalTensor<float> outScale2GM_;

    // TQue buffers for I/O
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x2InQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> xOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> y1Int8OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> y2Int8OutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outScaleQueue_;

    // TBuf for persistent weight data
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scales1Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scales2Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasBuf_;

    // Cast buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> x1CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x2CastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xOutCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasCastBuf_;

    // Work buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> workBufA_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> workBufB_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> workBufC_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;

    // Local tensors
    AscendC::LocalTensor<dataType> x1InLocal_;
    AscendC::LocalTensor<dataType> x2InLocal_;
    AscendC::LocalTensor<dataType> xOutLocal_;
    AscendC::LocalTensor<int8_t> y1Int8OutLocal_;
    AscendC::LocalTensor<int8_t> y2Int8OutLocal_;
    AscendC::LocalTensor<float> outScaleLocal_;
    AscendC::LocalTensor<float> gammaLocal_;
    AscendC::LocalTensor<float> betaLocal_;
    AscendC::LocalTensor<float> scales1Local_;
    AscendC::LocalTensor<float> scales2Local_;
    AscendC::LocalTensor<dataType> biasInLocal_;
    AscendC::LocalTensor<float> biasFp32Local_;
    AscendC::LocalTensor<float> x1Fp32_;
    AscendC::LocalTensor<float> x2Fp32_;
    AscendC::LocalTensor<float> xOutFp32_;
    AscendC::LocalTensor<float> workA_;
    AscendC::LocalTensor<float> workB_;
    AscendC::LocalTensor<float> workC_;
    AscendC::LocalTensor<uint8_t> reduceTmp_;
    AscendC::LocalTensor<float> sumLocal_;
};

// =========================================================================
// dtype dispatch helper
// =========================================================================

template <template <typename> class Kernel>
__aicore__ inline void DispatchByDtype(
    GM_ADDR x1, GM_ADDR x2,
    GM_ADDR gamma, GM_ADDR beta, GM_ADDR bias,
    GM_ADDR scales1, GM_ADDR scales2,
    GM_ADDR y1_int8, GM_ADDR y2_int8,
    GM_ADDR x_out, GM_ADDR out_scale1, GM_ADDR out_scale2,
    int32_t M, int32_t N,
    int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
    float eps, int64_t quantMode, int64_t hasBias,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x1, x2, gamma, beta, bias, scales1, scales2,
                    y1_int8, y2_int8, x_out, out_scale1, out_scale2,
                    M, N, blockM, usedCoreNum, tasksPerCore,
                    eps, quantMode, hasBias);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x1, x2, gamma, beta, bias, scales1, scales2,
                    y1_int8, y2_int8, x_out, out_scale1, out_scale2,
                    M, N, blockM, usedCoreNum, tasksPerCore,
                    eps, quantMode, hasBias);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x1, x2, gamma, beta, bias, scales1, scales2,
                    y1_int8, y2_int8, x_out, out_scale1, out_scale2,
                    M, N, blockM, usedCoreNum, tasksPerCore,
                    eps, quantMode, hasBias);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry point
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void add_layernorm_quant(
    GM_ADDR x1, GM_ADDR x2,
    GM_ADDR gamma, GM_ADDR beta, GM_ADDR bias,
    GM_ADDR scales1, GM_ADDR scales2,
    GM_ADDR y1_int8, GM_ADDR y2_int8,
    GM_ADDR x_out, GM_ADDR out_scale1, GM_ADDR out_scale2,
    int32_t M, int32_t N,
    int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
    float eps, int64_t quantMode, int64_t hasBias,
    int64_t dtypeFlag)
{
    DispatchByDtype<AddLayerNormQuantKernel>(
        x1, x2, gamma, beta, bias, scales1, scales2,
        y1_int8, y2_int8, x_out, out_scale1, out_scale2,
        M, N, blockM, usedCoreNum, tasksPerCore,
        eps, quantMode, hasBias, dtypeFlag);
}
