// AscendC AddLayerNormQuant kernel
// Add(x1, x2 [+bias]) → LayerNorm(gamma, beta) → Quantize(int8)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// =========================================================================
// Helper functions
// =========================================================================

template <typename T>
__aicore__ inline void MoveGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = count * static_cast<uint32_t>(sizeof(T));
    AscendC::DataCopyPadExtParams<T> pp;
    pp.isPad = true;
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void MoveUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = count * static_cast<uint32_t>(sizeof(T));
    AscendC::DataCopyPad(dst, src, cp);
}

template <typename T>
__aicore__ inline AscendC::RoundMode GetOutputRound()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void CastInFp32(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &buf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = buf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void CastOutFp32(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &buf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = buf.Get<float>();
        AscendC::Duplicate(src, static_cast<T>(0), count);
    }
}

// =========================================================================
// Kernel class
// =========================================================================

template <typename dataType>
class AddLayerNormQuantKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x1, GM_ADDR x2,
        GM_ADDR gamma, GM_ADDR beta, GM_ADDR bias,
        GM_ADDR scales1, GM_ADDR scales2,
        GM_ADDR y1Int8, GM_ADDR y2Int8,
        GM_ADDR xOut, GM_ADDR outScale1, GM_ADDR outScale2,
        int32_t M, int32_t N,
        int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
        float eps, int64_t qMode, int64_t hBias)
    {
        M_ = M; N_ = N; blockM_ = blockM;
        usedCoreNum_ = usedCoreNum; tasksPerCore_ = tasksPerCore;
        eps_ = eps; qMode_ = qMode; hBias_ = hBias;

        x1Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1),
                              static_cast<uint64_t>(M) * N);
        x2Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2),
                              static_cast<uint64_t>(M) * N);
        gammaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gamma), N);
        betaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(beta), N);
        biasGm_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(bias), N);
        s1Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scales1), N);
        s2Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scales2), N);
        y1Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y1Int8),
                             static_cast<uint64_t>(M) * N);
        y2Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y2Int8),
                             static_cast<uint64_t>(M) * N);
        xOutGm_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xOut),
                               static_cast<uint64_t>(M) * N);
        os1Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(outScale1), M);
        os2Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(outScale2), M);

        if ASCEND_IS_AIV { InitBuffers(); }
    }

    __aicore__ inline void InitBuffers()
    {
        sbRows_ = blockM_ / AscendC::GetSubBlockNum();

        // TQue for I/O
        pipe_.InitBuffer(inQ1_, BUFFER_NUM, N_ * sizeof(dataType));
        pipe_.InitBuffer(inQ2_, BUFFER_NUM, N_ * sizeof(dataType));
        pipe_.InitBuffer(outQX_, BUFFER_NUM, N_ * sizeof(dataType));
        pipe_.InitBuffer(outQY1_, BUFFER_NUM, N_ * sizeof(int8_t));
        pipe_.InitBuffer(outQY2_, BUFFER_NUM, N_ * sizeof(int8_t));
        pipe_.InitBuffer(outQScale_, BUFFER_NUM, 2 * sizeof(float));

        // Persistent weight tensors
        pipe_.InitBuffer(bufGamma_, N_ * sizeof(float));
        pipe_.InitBuffer(bufBeta_, N_ * sizeof(float));
        if (qMode_ == 1) {
            pipe_.InitBuffer(bufS1_, N_ * sizeof(float));
            pipe_.InitBuffer(bufS2_, N_ * sizeof(float));
        }
        if (hBias_) {
            pipe_.InitBuffer(bufBias_, N_ * sizeof(dataType));
        }

        // Cast buffers
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe_.InitBuffer(bufCast1_, N_ * sizeof(float));
            pipe_.InitBuffer(bufCast2_, N_ * sizeof(float));
            pipe_.InitBuffer(bufCastX_, N_ * sizeof(float));
            if (hBias_) pipe_.InitBuffer(bufCastBias_, N_ * sizeof(float));
        }

        // Work buffers (fp32)
        pipe_.InitBuffer(bufWkA_, N_ * sizeof(float));
        pipe_.InitBuffer(bufWkB_, N_ * sizeof(float));
        pipe_.InitBuffer(bufWkC_, N_ * sizeof(float));
        // Reduce buffer: N elements of float (for single-row ReduceSum 4-arg API)
        pipe_.InitBuffer(bufReduce_, N_ * sizeof(float));
        pipe_.InitBuffer(bufSum_, 16 * sizeof(float));
        pipe_.InitBuffer(bufClamp_, N_ * sizeof(float));
        // int32 temp buffer for float→int32→int8 cast chain
        pipe_.InitBuffer(bufI32_, N_ * sizeof(int32_t));

        // ── Preload persistent data ──
        gammaLoc_ = bufGamma_.Get<float>();
        MoveGmToUb<float>(gammaLoc_, gammaGm_, static_cast<uint32_t>(N_));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        betaLoc_ = bufBeta_.Get<float>();
        MoveGmToUb<float>(betaLoc_, betaGm_, static_cast<uint32_t>(N_));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        if (qMode_ == 1) {
            s1Loc_ = bufS1_.Get<float>();
            MoveGmToUb<float>(s1Loc_, s1Gm_, static_cast<uint32_t>(N_));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            s2Loc_ = bufS2_.Get<float>();
            MoveGmToUb<float>(s2Loc_, s2Gm_, static_cast<uint32_t>(N_));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
        }

        if (hBias_) {
            biasInLoc_ = bufBias_.Get<dataType>();
            MoveGmToUb<dataType>(biasInLoc_, biasGm_, static_cast<uint32_t>(N_));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            CastInFp32<dataType>(biasFp32Loc_, biasInLoc_, bufCastBias_, N_);
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int cid = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int sb = AscendC::GetSubBlockIdx();
            for (int li = 0; li < tasksPerCore_; ++li) {
                int bx = cid * tasksPerCore_ + li;
                if (bx * blockM_ >= M_) continue;
                for (int r = 0; r < sbRows_; ++r) {
                    int row = bx * blockM_ + sb * sbRows_ + r;
                    if (row < M_) DoRow(row);
                }
            }
        }
    }

private:
    __aicore__ inline void DoRow(int32_t row)
    {
        CopyIn(row);
        ComputeRow();
        CopyOut(row);
    }

    __aicore__ inline void CopyIn(int32_t row)
    {
        tX1_ = inQ1_.AllocTensor<dataType>();
        MoveGmToUb<dataType>(tX1_, x1Gm_[static_cast<uint64_t>(row) * N_],
                             static_cast<uint32_t>(N_));
        inQ1_.EnQue(tX1_);
        tX2_ = inQ2_.AllocTensor<dataType>();
        MoveGmToUb<dataType>(tX2_, x2Gm_[static_cast<uint64_t>(row) * N_],
                             static_cast<uint32_t>(N_));
        inQ2_.EnQue(tX2_);
    }

    __aicore__ inline void ComputeRow()
    {
        // Allocate outputs
        tXOut_ = outQX_.AllocTensor<dataType>();
        tY1Out_ = outQY1_.AllocTensor<int8_t>();
        tY2Out_ = outQY2_.AllocTensor<int8_t>();
        tScaleOut_ = outQScale_.AllocTensor<float>();

        // Work buffers
        wa_ = bufWkA_.Get<float>();
        wb_ = bufWkB_.Get<float>();
        wc_ = bufWkC_.Get<float>();
        wReduce_ = bufReduce_.Get<float>();
        wSum_ = bufSum_.Get<float>();
        wClamp_ = bufClamp_.Get<float>();
        wI32_ = bufI32_.Get<int32_t>();

        // DeQue
        tX1_ = inQ1_.DeQue<dataType>();
        tX2_ = inQ2_.DeQue<dataType>();

        // Cast → fp32
        CastInFp32<dataType>(x1Fp32_, tX1_, bufCast1_, N_);
        CastInFp32<dataType>(x2Fp32_, tX2_, bufCast2_, N_);
        CastOutFp32<dataType>(xOutFp32_, tXOut_, bufCastX_, N_);

        // ═══════════════════════════════════════════════════════════════
        // PHASE 1: x_out = x1 + x2 [+ bias]
        // ═══════════════════════════════════════════════════════════════
        AscendC::Add(xOutFp32_, x1Fp32_, x2Fp32_, N_);
        if (hBias_) AscendC::Add(xOutFp32_, xOutFp32_, biasFp32Loc_, N_);
        if constexpr (!std::is_same_v<dataType, float>) {
            AscendC::Cast(tXOut_, xOutFp32_, GetOutputRound<dataType>(), N_);
            AscendC::PipeBarrier<PIPE_V>();
        }
        outQX_.EnQue(tXOut_);

        // ═══════════════════════════════════════════════════════════════
        // PHASE 2: Reduce stats (sum, sum_sq → mean, var, rstd)
        // ═══════════════════════════════════════════════════════════════
        AscendC::ReduceSum<float>(wSum_, xOutFp32_, wReduce_, N_);
        AscendC::PipeBarrier<PIPE_V>();
        float sumX = wSum_.GetValue(0);

        // Re-acquire reduce buffer after first ReduceSum overwrites it
        wReduce_ = bufReduce_.Get<float>();
        AscendC::Mul(wa_, xOutFp32_, xOutFp32_, N_);
        AscendC::ReduceSum<float>(wSum_, wa_, wReduce_, N_);
        AscendC::PipeBarrier<PIPE_V>();
        float sumX2 = wSum_.GetValue(0);

        float invN = 1.0f / static_cast<float>(N_);
        float meanV = sumX * invN;
        float varV = sumX2 * invN - meanV * meanV;

        AscendC::Duplicate(wSum_, varV + eps_, 1);
        AscendC::Rsqrt(wSum_, wSum_, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        float rstdV = wSum_.GetValue(0);

        // ═══════════════════════════════════════════════════════════════
        // PHASE 3: LayerNorm y = (x-mean)*rstd*gamma + beta
        // ═══════════════════════════════════════════════════════════════
        AscendC::Adds(wa_, xOutFp32_, -meanV, N_);
        AscendC::Muls(wa_, wa_, rstdV, N_);
        AscendC::Mul(wb_, wa_, gammaLoc_, N_);
        AscendC::Add(wb_, wb_, betaLoc_, N_);

        // ═══════════════════════════════════════════════════════════════
        // PHASE 4: Quantize to int8
        // ═══════════════════════════════════════════════════════════════
        float scale1, scale2;
        if (qMode_ == 1) {
            AscendC::Mul(wa_, wb_, s1Loc_, N_);
            scale1 = QuantRow(wa_, tY1Out_);
            AscendC::Mul(wa_, wb_, s2Loc_, N_);
            scale2 = QuantRow(wa_, tY2Out_);
        } else {
            scale1 = QuantRow(wb_, tY1Out_);
            AscendC::Duplicate(tY2Out_, static_cast<int8_t>(0), N_);
            scale2 = scale1;
        }

        // ═══════════════════════════════════════════════════════════════
        // PHASE 5: Enqueue outputs
        // ═══════════════════════════════════════════════════════════════
        outQY1_.EnQue(tY1Out_);
        outQY2_.EnQue(tY2Out_);
        tScaleOut_.SetValue(0, scale1);
        tScaleOut_.SetValue(1, scale2);
        outQScale_.EnQue(tScaleOut_);

        inQ1_.FreeTensor(tX1_);
        inQ2_.FreeTensor(tX2_);
    }

    // Quantize: float[N] → int8[N], returns quant scale
    // Chain: float → int32 (RINT) → int8 (NONE)
    __aicore__ inline float QuantRow(
        AscendC::LocalTensor<float> &src,
        AscendC::LocalTensor<int8_t> &dst)
    {
        // abs max over N
        AscendC::Abs(wa_, src, N_);
        // Re-acquire reduce buffer
        wReduce_ = bufReduce_.Get<float>();
        AscendC::ReduceMax<float>(wSum_, wa_, wReduce_, N_);
        AscendC::PipeBarrier<PIPE_V>();
        float scale = wSum_.GetValue(0) / 127.0f;

        // wc = src / scale
        float iscale = 1.0f / (scale + 1e-12f);
        AscendC::Muls(wc_, src, iscale, N_);

        // Clamp [-128, 127]
        AscendC::Duplicate(wClamp_, -128.0f, N_);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Max(wa_, wc_, wClamp_, N_);
        AscendC::Duplicate(wClamp_, 127.0f, N_);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Min(wc_, wa_, wClamp_, N_);

        // Cast: float → int32 (RINT) → int8 (NONE)
        AscendC::Cast(wI32_, wc_, AscendC::RoundMode::CAST_RINT, N_);
        AscendC::Cast(dst, wI32_, AscendC::RoundMode::CAST_NONE, N_);

        return scale;
    }

    __aicore__ inline void CopyOut(int32_t row)
    {
        tXOut_ = outQX_.DeQue<dataType>();
        MoveUbToGm<dataType>(xOutGm_[static_cast<uint64_t>(row) * N_],
                             tXOut_, static_cast<uint32_t>(N_));
        outQX_.FreeTensor(tXOut_);

        tY1Out_ = outQY1_.DeQue<int8_t>();
        MoveUbToGm<int8_t>(y1Gm_[static_cast<uint64_t>(row) * N_],
                           tY1Out_, static_cast<uint32_t>(N_));
        outQY1_.FreeTensor(tY1Out_);

        tY2Out_ = outQY2_.DeQue<int8_t>();
        MoveUbToGm<int8_t>(y2Gm_[static_cast<uint64_t>(row) * N_],
                           tY2Out_, static_cast<uint32_t>(N_));
        outQY2_.FreeTensor(tY2Out_);

        tScaleOut_ = outQScale_.DeQue<float>();
        os1Gm_[row] = tScaleOut_.GetValue(0);
        os2Gm_[row] = tScaleOut_.GetValue(1);
        outQScale_.FreeTensor(tScaleOut_);
    }

    // ─── Members ───────────────────────────────────────────────────────
    int32_t M_ = 0, N_ = 0, blockM_ = 0;
    int32_t usedCoreNum_ = 0, tasksPerCore_ = 0;
    float eps_ = 0.0f;
    int64_t qMode_ = 0, hBias_ = 0;
    int sbRows_ = 0;
    AscendC::TPipe pipe_;

    AscendC::GlobalTensor<dataType> x1Gm_, x2Gm_, biasGm_, xOutGm_;
    AscendC::GlobalTensor<float> gammaGm_, betaGm_, s1Gm_, s2Gm_;
    AscendC::GlobalTensor<float> os1Gm_, os2Gm_;
    AscendC::GlobalTensor<int8_t> y1Gm_, y2Gm_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQ1_, inQ2_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQX_, outQY1_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQY2_, outQScale_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> bufGamma_, bufBeta_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufS1_, bufS2_, bufBias_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufCast1_, bufCast2_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufCastX_, bufCastBias_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufWkA_, bufWkB_, bufWkC_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufReduce_, bufSum_, bufClamp_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufI32_;

    AscendC::LocalTensor<dataType> tX1_, tX2_, tXOut_, biasInLoc_;
    AscendC::LocalTensor<int8_t> tY1Out_, tY2Out_;
    AscendC::LocalTensor<float> tScaleOut_;
    AscendC::LocalTensor<float> gammaLoc_, betaLoc_, s1Loc_, s2Loc_;
    AscendC::LocalTensor<float> biasFp32Loc_, x1Fp32_, x2Fp32_, xOutFp32_;
    AscendC::LocalTensor<float> wa_, wb_, wc_;
    AscendC::LocalTensor<float> wReduce_;
    AscendC::LocalTensor<float> wSum_, wClamp_;
    AscendC::LocalTensor<int32_t> wI32_;
};

// =========================================================================
// dtype dispatch
// =========================================================================

template <template <typename> class K>
__aicore__ inline void Dispatch(
    GM_ADDR x1, GM_ADDR x2,
    GM_ADDR gamma, GM_ADDR beta, GM_ADDR bias,
    GM_ADDR scales1, GM_ADDR scales2,
    GM_ADDR y1Int8, GM_ADDR y2Int8,
    GM_ADDR xOut, GM_ADDR outScale1, GM_ADDR outScale2,
    int32_t M, int32_t N,
    int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
    float eps, int64_t qMode, int64_t hBias,
    int64_t flag)
{
    if (flag == 0) {
        K<float> k; k.Init(x1, x2, gamma, beta, bias, scales1, scales2,
                           y1Int8, y2Int8, xOut, outScale1, outScale2,
                           M, N, blockM, usedCoreNum, tasksPerCore,
                           eps, qMode, hBias); k.Process();
    } else if (flag == 1) {
        K<half> k; k.Init(x1, x2, gamma, beta, bias, scales1, scales2,
                          y1Int8, y2Int8, xOut, outScale1, outScale2,
                          M, N, blockM, usedCoreNum, tasksPerCore,
                          eps, qMode, hBias); k.Process();
    } else {
        K<bfloat16_t> k; k.Init(x1, x2, gamma, beta, bias, scales1, scales2,
                                y1Int8, y2Int8, xOut, outScale1, outScale2,
                                M, N, blockM, usedCoreNum, tasksPerCore,
                                eps, qMode, hBias); k.Process();
    }
}

// =========================================================================
// Entry point — dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void add_layernorm_quant(
    GM_ADDR x1, GM_ADDR x2,
    GM_ADDR gamma, GM_ADDR beta, GM_ADDR bias,
    GM_ADDR scales1, GM_ADDR scales2,
    GM_ADDR y1Int8, GM_ADDR y2Int8,
    GM_ADDR xOut, GM_ADDR outScale1, GM_ADDR outScale2,
    int32_t M, int32_t N,
    int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
    float eps, int64_t qMode, int64_t hBias,
    int64_t flag)
{
    Dispatch<AddLayerNormQuantKernel>(
        x1, x2, gamma, beta, bias, scales1, scales2,
        y1Int8, y2Int8, xOut, outScale1, outScale2,
        M, N, blockM, usedCoreNum, tasksPerCore,
        eps, qMode, hBias, flag);
}
