// AscendC AddLayerNormQuant kernel
// Add(x1, x2 [+bias]) → LayerNorm(gamma, beta) → Quantize scale + clamp
// Outputs clamped float values; model_new_ascendc.py casts to int8

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// =========================================================================
// Helpers
// =========================================================================

template <typename T>
__aicore__ inline void LoadToUb(
    AscendC::LocalTensor<T> &dst, const AscendC::GlobalTensor<T> &src, uint32_t n)
{
    AscendC::DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = n * static_cast<uint32_t>(sizeof(T));
    AscendC::DataCopyPadExtParams<T> pp;
    pp.isPad = true;
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StoreToGm(
    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t n)
{
    AscendC::DataCopyExtParams cp;
    cp.blockCount = 1;
    cp.blockLen = n * static_cast<uint32_t>(sizeof(T));
    AscendC::DataCopyPad(dst, src, cp);
}

template <typename T>
inline AscendC::RoundMode RMode()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) return AscendC::RoundMode::CAST_ROUND;
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void InFp32(
    AscendC::LocalTensor<float> &d, AscendC::LocalTensor<T> &s,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &b, int32_t n)
{
