// =========================================================================
// Kernel
// =========================================================================

template <typename dataType>
class ALQKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR beta, GM_ADDR bias,
        GM_ADDR s1, GM_ADDR s2,
        GM_ADDR y1, GM_ADDR y2, GM_ADDR xo,
        GM_ADDR os1, GM_ADDR os2,
        int32_t M, int32_t N, int32_t bM, int32_t uC, int32_t tpc,
        float eps, int64_t qM, int64_t hB)
    {
        M_=M; N_=N; bM_=bM; uC_=uC; tpc_=tpc; eps_=eps; qM_=qM; hB_=hB;
        x1G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), (uint64_t)M*N);
        x2G_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), (uint64_t)M*N);
        gG_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gamma), N);
        bG_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(beta), N);
        biG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(bias), N);
        s1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(s1), N);
        s2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(s2), N);
        y1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y1), (uint64_t)M*N);
        y2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y2), (uint64_t)M*N);
        xoG_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xo), (uint64_t)M*N);
        o1G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(os1), M);
        o2G_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(os2), M);
        if ASCEND_IS_AIV { BufInit(); }
    }

    __aicore__ inline void BufInit()
    {
        sb_ = bM_ / AscendC::GetSubBlockNum();
        p_.InitBuffer(iQ1_, BUFFER_NUM, N_*sizeof(dataType));
        p_.InitBuffer(iQ2_, BUFFER_NUM, N_*sizeof(dataType));
        p_.InitBuffer(oQX_, BUFFER_NUM, N_*sizeof(dataType));
        p_.InitBuffer(oQY1_, BUFFER_NUM, N_*sizeof(float));
        p_.InitBuffer(oQY2_, BUFFER_NUM, N_*sizeof(float));
        p_.InitBuffer(oQS_, BUFFER_NUM, 2*sizeof(float));
        p_.InitBuffer(bGam_, N_*sizeof(float)); p_.InitBuffer(bBet_, N_*sizeof(float));
        if (qM_==1) { p_.InitBuffer(bS1_, N_*sizeof(float)); p_.InitBuffer(bS2_, N_*sizeof(float)); }
        if (hB_) p_.InitBuffer(bBi_, N_*sizeof(dataType));
        if constexpr (!std::is_same_v<dataType, float>) {
            p_.InitBuffer(bC1_, N_*sizeof(float)); p_.InitBuffer(bC2_, N_*sizeof(float));
            p_.InitBuffer(bCX_, N_*sizeof(float));
            if (hB_) p_.InitBuffer(bCB_, N_*sizeof(float));
        }
        p_.InitBuffer(bwA_, N_*sizeof(float)); p_.InitBuffer(bwB_, N_*sizeof(float));
        p_.InitBuffer(bwC_, N_*sizeof(float));
        p_.InitBuffer(bRed_, N_*sizeof(float)); p_.InitBuffer(bSum_, 16*sizeof(float));
        p_.InitBuffer(bClp_, N_*sizeof(float));

        gL_ = bGam_.Get<float>(); LoadToUb(gL_, gG_, (uint32_t)N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        bL_ = bBet_.Get<float>(); LoadToUb(bL_, bG_, (uint32_t)N_);
        AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        if (qM_==1) {
            s1L_ = bS1_.Get<float>(); LoadToUb(s1L_, s1G_, (uint32_t)N_);
            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
            s2L_ = bS2_.Get<float>(); LoadToUb(s2L_, s2G_, (uint32_t)N_);
            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        }
        if (hB_) {
            biL_ = bBi_.Get<dataType>(); LoadToUb(biL_, biG_, (uint32_t)N_);
            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
            InFp32<dataType>(bFL_, biL_, bCB_, N_);
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int c = AscendC::GetBlockIdx()/AscendC::GetSubBlockNum();
            int s = AscendC::GetSubBlockIdx();
            for (int li=0; li<tpc_; ++li) {
                int bx = c*tpc_+li; if (bx*bM_>=M_) continue;
                for (int r=0; r<sb_; ++r) {
                    int row = bx*bM_+s*sb_+r; if (row<M_) Row(row);
                }
            }
        }
    }

private:
    __aicore__ inline void Row(int32_t row) { CopyIn(row); Comp(); CopyOut(row); }

    __aicore__ inline void CopyIn(int32_t row)
    {
        tX1_=iQ1_.AllocTensor<dataType>();
        LoadToUb(tX1_, x1G_[(uint64_t)row*N_], (uint32_t)N_); iQ1_.EnQue(tX1_);
        tX2_=iQ2_.AllocTensor<dataType>();
        LoadToUb(tX2_, x2G_[(uint64_t)row*N_], (uint32_t)N_); iQ2_.EnQue(tX2_);
    }

    __aicore__ inline void Comp()
    {
        tXO_=oQX_.AllocTensor<dataType>();
        tY1_=oQY1_.AllocTensor<float>();
        tY2_=oQY2_.AllocTensor<float>();
        tS_=oQS_.AllocTensor<float>();
        wA_=bwA_.Get<float>(); wB_=bwB_.Get<float>(); wC_=bwC_.Get<float>();
        wR_=bRed_.Get<float>(); wS_=bSum_.Get<float>(); wL_=bClp_.Get<float>();

        tX1_=iQ1_.DeQue<dataType>(); tX2_=iQ2_.DeQue<dataType>();
        InFp32<dataType>(x1F_, tX1_, bC1_, N_);
        InFp32<dataType>(x2F_, tX2_, bC2_, N_);
        OutFp32<dataType>(xoF_, tXO_, bCX_, N_);

        // PHASE 1: x_out = x1 + x2 [+ bias]
        AscendC::Add(xoF_, x1F_, x2F_, N_);
        if (hB_) AscendC::Add(xoF_, xoF_, bFL_, N_);
        if constexpr (!std::is_same_v<dataType, float>) {
            AscendC::Cast(tXO_, xoF_, RMode<dataType>(), N_); AscendC::PipeBarrier<PIPE_V>();
        }
        oQX_.EnQue(tXO_);

        // PHASE 2: stats
        AscendC::ReduceSum<float>(wS_, xoF_, wR_, N_);
        AscendC::PipeBarrier<PIPE_V>(); float sx=wS_.GetValue(0);
        wR_=bRed_.Get<float>();
        AscendC::Mul(wA_, xoF_, xoF_, N_);
        AscendC::ReduceSum<float>(wS_, wA_, wR_, N_);
        AscendC::PipeBarrier<PIPE_V>(); float sx2=wS_.GetValue(0);
        float inv=1.0f/(float)N_, mv=sx*inv, vv=sx2*inv - mv*mv;
        AscendC::Duplicate(wS_, vv+eps_, 1);
        AscendC::Rsqrt(wS_, wS_, 1); AscendC::PipeBarrier<PIPE_ALL>();
        float rv=wS_.GetValue(0);

        // PHASE 3: layernorm
        AscendC::Adds(wA_, xoF_, -mv, N_); AscendC::Muls(wA_, wA_, rv, N_);
        AscendC::Mul(wB_, wA_, gL_, N_); AscendC::Add(wB_, wB_, bL_, N_);

        // PHASE 4: quantize → clamped float output
        float s1, s2;
        if (qM_==1) {
            AscendC::Mul(wA_, wB_, s1L_, N_); s1 = Quant(wA_, tY1_);
            AscendC::Mul(wA_, wB_, s2L_, N_); s2 = Quant(wA_, tY2_);
        } else {
            s1 = Quant(wB_, tY1_);
            AscendC::Duplicate(tY2_, 0.0f, N_); s2 = s1;
        }

        oQY1_.EnQue(tY1_); oQY2_.EnQue(tY2_);
        tS_.SetValue(0,s1); tS_.SetValue(1,s2); oQS_.EnQue(tS_);
        iQ1_.FreeTensor(tX1_); iQ2_.FreeTensor(tX2_);
    }

    __aicore__ inline float Quant(AscendC::LocalTensor<float> &src,
                                   AscendC::LocalTensor<float> &dst)
    {
        AscendC::Abs(wA_, src, N_);
        wR_=bRed_.Get<float>();
        AscendC::ReduceMax<float>(wS_, wA_, wR_, N_);
        AscendC::PipeBarrier<PIPE_V>();
        float sc=wS_.GetValue(0)/127.0f;
        float is=1.0f/(sc+1e-12f);
        AscendC::Muls(wC_, src, is, N_);
        AscendC::Duplicate(wL_, -128.0f, N_); AscendC::PipeBarrier<PIPE_V>();
        AscendC::Max(wA_, wC_, wL_, N_);
        AscendC::Duplicate(wL_, 127.0f, N_); AscendC::PipeBarrier<PIPE_V>();
        AscendC::Min(dst, wA_, wL_, N_);
        return sc;
    }

    __aicore__ inline void CopyOut(int32_t row)
    {
        tXO_=oQX_.DeQue<dataType>(); StoreToGm(xoG_[(uint64_t)row*N_], tXO_, (uint32_t)N_); oQX_.FreeTensor(tXO_);
        tY1_=oQY1_.DeQue<float>(); StoreToGm(y1G_[(uint64_t)row*N_], tY1_, (uint32_t)N_); oQY1_.FreeTensor(tY1_);
        tY2_=oQY2_.DeQue<float>(); StoreToGm(y2G_[(uint64_t)row*N_], tY2_, (uint32_t)N_); oQY2_.FreeTensor(tY2_);
        tS_=oQS_.DeQue<float>();
        float sv1=tS_.GetValue(0), sv2=tS_.GetValue(1); oQS_.FreeTensor(tS_);
        AscendC::LocalTensor<float> sb=bSum_.Get<float>();
        AscendC::Duplicate(sb, sv1, 1); StoreToGm(o1G_[row], sb, 1);
        AscendC::Duplicate(sb, sv2, 1); StoreToGm(o2G_[row], sb, 1);
    }

    int32_t M_=0,N_=0,bM_=0,uC_=0,tpc_=0,sb_=0;
    float eps_=0; int64_t qM_=0,hB_=0;
    AscendC::TPipe p_;
    AscendC::GlobalTensor<dataType> x1G_,x2G_,biG_,xoG_;
    AscendC::GlobalTensor<float> gG_,bG_,s1G_,s2G_,y1G_,y2G_,o1G_,o2G_;
    AscendC::TQue<AscendC::TPosition::VECIN,BUFFER_NUM> iQ1_,iQ2_;
    AscendC::TQue<AscendC::TPosition::VECOUT,BUFFER_NUM> oQX_,oQY1_,oQY2_,oQS_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bGam_,bBet_,bS1_,bS2_,bBi_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bC1_,bC2_,bCX_,bCB_,bwA_,bwB_,bwC_,bRed_,bSum_,bClp_;
    AscendC::LocalTensor<dataType> tX1_,tX2_,tXO_,biL_;
    AscendC::LocalTensor<float> tY1_,tY2_,tS_,gL_,bL_,s1L_,s2L_,bFL_;
    AscendC::LocalTensor<float> x1F_,x2F_,xoF_,wA_,wB_,wC_,wR_,wS_,wL_;
};

template <template <typename> class K>
__aicore__ inline void D(
    GM_ADDR x1,GM_ADDR x2,GM_ADDR g,GM_ADDR b,GM_ADDR bi,GM_ADDR s1,GM_ADDR s2,
    GM_ADDR y1,GM_ADDR y2,GM_ADDR xo,GM_ADDR o1,GM_ADDR o2,
    int32_t M,int32_t N,int32_t bM,int32_t uC,int32_t tp,
    float e,int64_t qM,int64_t hB,int64_t fl)
{
    if(fl==0){K<float>k;k.Init(x1,x2,g,b,bi,s1,s2,y1,y2,xo,o1,o2,M,N,bM,uC,tp,e,qM,hB);k.Process();}
    else if(fl==1){K<half>k;k.Init(x1,x2,g,b,bi,s1,s2,y1,y2,xo,o1,o2,M,N,bM,uC,tp,e,qM,hB);k.Process();}
    else{K<bfloat16_t>k;k.Init(x1,x2,g,b,bi,s1,s2,y1,y2,xo,o1,o2,M,N,bM,uC,tp,e,qM,hB);k.Process();}
}

extern "C" __global__ __aicore__ void add_layernorm_quant(
    GM_ADDR x1,GM_ADDR x2,GM_ADDR g,GM_ADDR b,GM_ADDR bi,GM_ADDR s1,GM_ADDR s2,
    GM_ADDR y1,GM_ADDR y2,GM_ADDR xo,GM_ADDR o1,GM_ADDR o2,
